        pairs=[]
        for r,c in pts:
            for dr in (-1,1):
                for dc in (-1,1):
                    if (r+dr,c+dc) in pts:
                        pairs.append((r,c,dr,dc))
        if pairs:
            # Choose the pair whose forward endpoint is farther down-grid.
            r,c,dr,dc=max(pairs,key=lambda p:p[0]+p[2])
            while 0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==grid[0][0]:
                r+=dr; c+=dc
                out[r][c]=color
    return out

